-- Huitième lot de builds fournis par le staff (19/08/2026) — voir
-- 012_best_builds.sql pour le contexte de la table. Pam avait été oubliée
-- dans le lot précédent (image non reçue à ce moment-là).
insert into best_builds (brawler_slug, brawler_name, comment) values
  ('pam', 'Pam', 'Pam est protégée des aggros corps à corps grâce à son excellent gadget qui vole leurs munitions. Une tourelle bien protégée et le pouvoir star qui vous soigne à chaque attaque vous rendent très difficile à éliminer. Pam peut tout à fait utiliser le gear vision avec sa grande portée et ses nombreux projectiles. L''autre pouvoir star peut surprendre vos adversaires, mais n''a d''utilité que sur les adversaires de très courte portée.'),
  ('colette', 'Colette', 'Avec Colette, notre objectif est d''anéantir les tanks. Le gadget vous permet d''aligner vos ennemis, et le pouvoir star permet à votre super de les tuer à vitesse grand V, en plus de vous protéger des assassins. Pour avoir encore plus d''avantage contre ces derniers, je vous recommande le gear vision. Le pouvoir star du bouclier reste excellent : il vous permet d''atteindre plus facilement le coffre en Braquage, surtout s''il est défendu par des snipers.'),
  ('belle', 'Belle', 'Belle, le sniper le plus sûr depuis sa sortie. Les rebonds avec le gadget, c''est marrant, mais le piège est bien meilleur : il vous permet de toucher les ennemis ralentis, et donc d''obtenir le bouclier offert par le pouvoir star, en plus de vous défendre contre les assassins. En parlant d''assassins, l''autre pouvoir star est tout à fait excellent contre eux : il les empêche de vous attaquer pendant une grande durée si vous touchez votre super. Le gear vision est excellent, Belle possède une grande portée et des attaques qui rebondissent.')
on conflict (brawler_slug) do nothing;
